def solve():
    n = int(input())
    d = list(map(int, input().split()))

    total_sum = sum(d)
    if total_sum % 2 != 0:
        print(0)
        return

    target = total_sum // 2
    prefix_sum = [0] * (n + 1)
    suffix_sum = [0] * (n + 1)

    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + d[i]

    for i in range(n - 1, -1, -1):
        suffix_sum[i] = suffix_sum[i + 1] + d[i]

    max_sum = 0
    for i in range(n + 1):
        if prefix_sum[i] == target:
            for j in range(n, i - 1, -1):
                if suffix_sum[j] == target:
                    max_sum = max(max_sum, prefix_sum[i])
                    break

    print(max_sum)

solve()
